import{_ as i,C as a,o,c as r,ai as e,E as s}from"./chunks/framework.D78JMWkX.js";const n="/OS_Learning/assets/image-20260609112135062.B83W2XPW.png",p="/OS_Learning/assets/image-20260609112422611.4rh8_Otn.png",d="/OS_Learning/assets/image-20260609114902655.DICJqf1H.png",c="/OS_Learning/assets/image-20260609144101331.DDXR-5ML.png",f=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"IO管理/5_2 IO软硬件组成.md","filePath":"IO管理/5_2 IO软硬件组成.md","lastUpdated":1781416353000}'),g={name:"IO管理/5_2 IO软硬件组成.md"};function h(_,t,u,O,I,m){const l=a("QuizSet");return o(),r("div",null,[t[0]||(t[0]=e('<h2 id="i-o-硬件组成" tabindex="-1">I/O 硬件组成 <a class="header-anchor" href="#i-o-硬件组成" aria-label="Permalink to &quot;I/O 硬件组成&quot;">​</a></h2><p><img src="'+n+'" alt=""></p><h3 id="设备控制器" tabindex="-1">设备控制器 <a class="header-anchor" href="#设备控制器" aria-label="Permalink to &quot;设备控制器&quot;">​</a></h3><p><img src="'+p+'" alt=""></p><p><strong>组成：</strong></p><ul><li>寄存器：数据、状态、控制</li><li>设备接口：数据信号、控制信号、状态信号</li><li>I/O逻辑：用于实现CPU对I/O设备的控制</li></ul><p><strong>功能：</strong></p><ol><li>处理CPU命令（接受CPU命令、识别设备地址、追踪设备状态）</li><li>数据交换</li><li>缓冲区</li><li>对设备传来的数据进行差错检测</li></ol><h3 id="i-o端口地址" tabindex="-1">I/O端口地址 <a class="header-anchor" href="#i-o端口地址" aria-label="Permalink to &quot;I/O端口地址&quot;">​</a></h3><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>I/O端口地址：</strong></p><ul><li>接口电路中每个寄存器具有唯一的地址</li><li>所有I/O端口地址形成I/O端口的地址空间（受OS保护）</li></ul><p>主要有以下两种形式：</p><ul><li><strong>内存映像编址（内存映像I/O模式）：</strong> 控制器的内存/寄存器作为物理内存空间的一部分</li><li><strong>I/O独立编址（I/O专用指令）：</strong> 例如 Intel 体系架构 in/out 指令</li></ul></div><table tabindex="0"><thead><tr><th></th><th>内存映射I/O</th><th>I/O独立编址</th></tr></thead><tbody><tr><td>优点</td><td>1. 可复用原有保护机制<br>2. 可复用原有访存指令</td><td>1. 外设不占用内存地址空间<br>2. 编程时易于区分内存与I/O操作</td></tr><tr><td>缺点</td><td><strong>不允许对一个控制寄存器内容进行高速缓存</strong></td><td>I/O端口指令少，不灵活</td></tr></tbody></table><p>关于<strong>不允许对一个控制寄存器内容进行高速缓存</strong>：</p><ul><li>设备状态从外部变化时，缓存不更新，产生问题</li><li>某些操作需要改变设备状态及时向外反馈</li></ul><hr><h2 id="i-o软件组成" tabindex="-1">I/O软件组成 <a class="header-anchor" href="#i-o软件组成" aria-label="Permalink to &quot;I/O软件组成&quot;">​</a></h2><p><img src="'+d+'" alt=""></p><p><strong>分层设计思想：</strong> 每一层都执行OS所需的功能的一个子集，它依赖于更低一层所执行的更原始的功能，从而隐藏这些功能的细节；同时又给高一层提供服务。</p><p>高层较清晰，底层偏复杂。</p><h3 id="设备独立性" tabindex="-1">设备独立性 <a class="header-anchor" href="#设备独立性" aria-label="Permalink to &quot;设备独立性&quot;">​</a></h3><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>逻辑设备：</strong>在应用程序中，使用逻辑设备名称来请求使用某类设备</p><p><strong>物理设备：</strong>系统在实际执行时，还必须使用物理设备名称</p><p><strong>设备独立性</strong>是应用程序不依赖某一台具体物理设备，程序只提出抽象操作或使用逻辑设备名。系统需具有将逻辑设备名称转换为某物理设备名称的功能，类似于物理地址与逻辑地址的概念</p></div><p>实现设备独立性的好处：</p><ul><li>设备分配时的灵活性：可让多个同功能设备使用同一个逻辑名称，当某台设备忙碌或不可用时，系统仍可从同类设备中选择其他空闲设备。</li><li>易于实现I/O重定向</li></ul><p>为了实现设备的独立性，系统必须置一张<strong>逻辑设备表LUT(Logical Unit Table)</strong>，用于将应用程序中所使用的逻辑设备名映射为物理设备名。</p><p><img src="'+c+'" alt=""></p><p>LUT的设置有两种方式：</p><ul><li>整个系统设置一张</li><li>为每个用户设置一张</li></ul><h3 id="设备驱动程序" tabindex="-1">设备驱动程序 <a class="header-anchor" href="#设备驱动程序" aria-label="Permalink to &quot;设备驱动程序&quot;">​</a></h3><p><strong>任务：</strong>接收来自与设备无关的上层软件的抽象请求，并执行这个请求</p><p>最简单的例如read、write等</p><p><strong>特点：</strong></p><ul><li>I/O进程与设备控制器之间的通信程序</li><li>与设备特性、硬件和I/O控制方式紧密相关</li></ul><p><strong>组成：</strong></p><ul><li>自动配置和初始化子程序：登记、初始化、卸载等</li><li>I/O操作子程序：启动I/O或将I/O请求挂入请求队列</li><li>中断服务子程序：唤醒等待I/O的进程、启动下一个I/O</li></ul><p><strong>共性部分：</strong></p><ul><li>核心代码：设备驱动是内核的一部分</li><li>核心接口：为内核提供一个标准接口（所谓接口就是可调用的函数）</li><li>核心机制与服务：可使用标准的内核服务，例如内存分配、中断发送和等待队列等</li></ul><h2 id="复习题" tabindex="-1">复习题 <a class="header-anchor" href="#复习题" aria-label="Permalink to &quot;复习题&quot;">​</a></h2>',36)),s(l,{collection:"io"})])}const q=i(g,[["render",h]]);export{f as __pageData,q as default};
